item.command:
/bin/bash -lc "python - <<'PY'
import urllib.parse, urllib.request
for term in ['axolotl[All Fields] AND ATAC','Ambystoma mexicanum[Organism] AND ATAC','axolotl organ chromatin accessibility']:
 u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=gds&retmode=json&retmax=20&term='+urllib.parse.quote(term)
 print('\\n',term)
 try: print(urllib.request.urlopen(u,timeout=30).read().decode()[:10000])
 except Exception as e: print(type(e).__name__,e)
PY"

