/bin/bash -lc "python - <<'PY'
import urllib.request,re
for gsm in ['GSM8426940','GSM8426943','GSM8426946','GSM8426949','GSM8426952','GSM8426953','GSM8426954','GSM8426957','GSM8426960','GSM8426963','GSM8426966','GSM8426967','GSM8426970','GSM8426973']:
 u='https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc='+gsm+'&targ=self&form=text&view=full'
 s=urllib.request.urlopen(u,timeout=30).read().decode('utf8','ignore')
 print('\\n---',gsm)
 for line in s.splitlines():
  if line.startswith('"'!Sample_'"'):
   print(line)
PY"

